extra_css:
/* Silver Screen surfaces: black velvet boards in gilded art deco frames (a thin gold rule, a gap, a fainter rule), lit from
   above by the screen; hover brings the frame up like the house lights. Headings in silver nitrate (a cool white-to-silver gradient).
   Scoped to own surfaces only. */
html[data-atmo="silverscreen"] .card, html[data-atmo="silverscreen"] .panel, html[data-atmo="silverscreen"] .gx-card {
  background: radial-gradient(130% 80% at 50% 0%, rgba(240,232,214,.06), transparent 60%), linear-gradient(180deg, rgba(30,23,25,.9), rgba(10,8,9,.95));
  backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px);
  box-shadow: inset 0 0 0 1px rgba(220,184,98,.34), inset 0 0 0 4px rgba(10,8,9,.9), inset 0 0 0 5px rgba(220,184,98,.14), 0 18px 46px rgba(0,0,0,.75);
  transition: box-shadow .4s ease, transform .5s cubic-bezier(.2,1,.3,1), background .6s ease; }
html[data-atmo="silverscreen"] .card:hover, html[data-atmo="silverscreen"] .gx-card:hover {
  transform: translateY(-2px);
  background: radial-gradient(130% 80% at 50% 0%, rgba(240,232,214,.1), transparent 62%), linear-gradient(180deg, rgba(36,28,30,.92), rgba(12,9,10,.95));
  box-shadow: inset 0 0 0 1px rgba(232,200,120,.6), inset 0 0 0 4px rgba(10,8,9,.9), inset 0 0 0 5px rgba(220,184,98,.3), 0 0 26px rgba(220,184,98,.1), 0 22px 54px rgba(0,0,0,.78); }
html[data-atmo="silverscreen"] h1, html[data-atmo="silverscreen"] h2 { background: linear-gradient(180deg, #ffffff, #dcdad6 48%, #9c9890); -webkit-background-clip: text; background-clip: text; color: transparent; }
html[data-atmo="silverscreen"] h1 { filter: drop-shadow(0 2px 14px rgba(0,0,0,.9)) drop-shadow(0 0 2px rgba(0,0,0,.85)); }

